/**
 * AiHero — the centered AI call-to-action hero used by the Factions + Analysis
 * steps (cog-* translation of wizard.jsx `.ai-hero`). Brand-blue mark (NO
 * violet); a `loading` state swaps the glyph for a spinner. The optional
 * `context` list renders the location/objective/time summary rows; `children`
 * holds the action buttons.
 */

import type { ReactElement, ReactNode } from "react";
import { WizardIcon, type WizardIconName } from "../icons";
import { ThinkingOrb } from "./thinkingOrb/ThinkingOrb";
import type { ThinkingOrbMode } from "./thinkingOrb/orbMath";

export interface AiHeroContextRow {
  readonly label: string;
  readonly value: string;
}

export interface AiHeroProps {
  readonly icon?: WizardIconName;
  readonly loading?: boolean;
  readonly orbMode?: ThinkingOrbMode;
  readonly heading: string;
  readonly body: string;
  readonly context?: readonly AiHeroContextRow[];
  readonly children?: ReactNode;
}

export function AiHero({
  icon = "sparkles",
  loading = false,
  orbMode = "orbits",
  heading,
  body,
  context,
  children,
}: AiHeroProps): ReactElement {
  return (
    <div className="mx-auto flex max-w-cog-39 flex-col items-center gap-cog-4 text-center">
      {loading ? (
        <span className="inline-flex h-cog-8-5 w-cog-8-5 items-center justify-center">
          <ThinkingOrb size={56} mode={orbMode} />
        </span>
      ) : (
        <span
          aria-hidden="true"
          className="inline-flex h-cog-8-5 w-cog-8-5 items-center justify-center rounded-2xl bg-cog-blue-600 text-white shadow-cog-e2 dark:bg-cog-blue-300 dark:text-cog-blue-900"
        >
          <WizardIcon name={icon} size={26} />
        </span>
      )}
      {/* The live region wraps the already-visible copy, and is present
          UNCONDITIONALLY (not just while loading): assistive tech only
          announces mutations to a region that was ALREADY live at the time
          of the mutation, so gating role="status" on `loading` meant the
          exact commit that swaps the copy to the loading text — the one
          announcement that matters — would frequently go unannounced (the
          region and the mutation would arrive in the same commit). Keeping
          it permanently live also makes this the single, stable status node
          for the whole card: JobStatusInline's "hero" variant defers to it
          and never renders a region of its own (see JobStatusInline.tsx),
          so nesting it beneath (e.g. the cancelled outcome) never produces a
          second live region. The orb itself stays aria-hidden. */}
      <div
        role="status"
        aria-live="polite"
        className="flex flex-col items-center gap-cog-4"
      >
        <h2 className="text-heading-md font-semibold text-cog-text-primary">
          {heading}
        </h2>
        <p className="text-body-md text-cog-text-secondary">{body}</p>
      </div>

      {context && context.length > 0 && (
        <dl className="w-full divide-y divide-cog-divider rounded-lg border border-cog-border bg-cog-surface-subtle text-start">
          {context.map((row) => (
            <div key={row.label} className="flex gap-cog-4 px-cog-4 py-cog-2">
              <dt className="w-cog-11 shrink-0 text-body-sm text-cog-text-tertiary">
                {row.label}
              </dt>
              <dd className="min-w-cog-0 flex-1 truncate text-body-sm text-cog-text-primary">
                {row.value}
              </dd>
            </div>
          ))}
        </dl>
      )}

      {children && <div className="flex flex-wrap justify-center gap-cog-2">{children}</div>}
    </div>
  );
}


