/**
 * Callout — informational panel (cog-* translation of ui.jsx `Callout`). The
 * AI variant uses the brand-blue soft treatment (NO AI-violet — design rule).
 * Renders an icon + optional title + body.
 */

import type { ReactElement, ReactNode } from "react";
import { WizardIcon, type WizardIconName } from "../icons";

export interface CalloutProps {
  readonly variant?: "default" | "ai";
  readonly icon?: WizardIconName;
  readonly title?: string;
  readonly children: ReactNode;
}

export function Callout({
  variant = "default",
  icon = "info",
  title,
  children,
}: CalloutProps): ReactElement {
  const ai = variant === "ai";
  return (
    <div
      className={[
        "flex gap-cog-3 rounded-lg border p-cog-4",
        ai
          ? "border-cog-blue-600/30 bg-cog-blue-600/5 dark:border-cog-blue-300/30 dark:bg-cog-blue-300/10"
          : "border-cog-border bg-cog-surface-subtle",
      ].join(" ")}
    >
      <span
        aria-hidden="true"
        className={
          ai
            ? "text-cog-blue-600 dark:text-cog-blue-300"
            : "text-cog-text-secondary"
        }
      >
        <WizardIcon name={icon} size={16} />
      </span>
      <div className="flex flex-1 flex-col gap-cog-0-5">
        {title && (
          <div className="text-body-md font-semibold text-cog-text-primary">
            {title}
          </div>
        )}
        <div className="text-body-sm text-cog-text-secondary">{children}</div>
      </div>
    </div>
  );
}


