/**
 * ChangeMethodLink — the "‹ Change method" back-out control shared by
 * Factions/Analysis/Context: swaps a step's active method panel back to its
 * PickCard row. A real <button> (it mutates local state, not navigation), so
 * it composes into any panel's flow without a separate a11y story.
 *
 * The leading chevron is `ChevronLeft`, which points visually toward the
 * reading start in LTR. Under RTL (ar-AE) "back toward the start" is visually
 * rightward, so the glyph is mirrored with the `rtl:-scale-x-100` utility —
 * this MFE's established mirroring idiom (ExerciseCard, ExerciseShell,
 * ProfileDetailRoute) — rather than swapping in a hardcoded `›` character
 * that would point the wrong way once mirrored again by the browser's own
 * bidi handling.
 *
 * The mirroring is pure CSS on purpose: the variant compiles to a
 * `[dir="rtl"]`-scoped rule, so orientation follows the ambient `dir` with
 * zero JS. Reading `document.documentElement.dir` during render instead would
 * be an un-subscribed read of mutable external state — the wizard overlay
 * stays mounted across a locale switch to ar-AE (platform-chrome flips
 * `<html dir>`), so the chevron would keep its stale orientation until some
 * unrelated re-render — and it would assume a DOM exists at render time.
 */

import type { ReactElement } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { WizardIcon } from "../icons";

export interface ChangeMethodLinkProps {
  readonly onClick: () => void;
}

export function ChangeMethodLink({
  onClick,
}: ChangeMethodLinkProps): ReactElement {
  return (
    <button
      type="button"
      onClick={onClick}
      className="inline-flex w-fit items-center gap-cog-1 rounded-md text-body-sm font-medium text-cog-text-secondary hover:text-cog-text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-2"
    >
      <WizardIcon name="chevronLeft" size={14} className="rtl:-scale-x-100" />
      {m.range_wizard_change_method()}
    </button>
  );
}


