/**
 * Checkbox — square check toggle (cog-* translation of ui.jsx `Checkbox`).
 * Thin wrapper over `@omnicore-platform/ui`'s Radix-backed `Checkbox`,
 * keeping this module's own `checked`/`onChange` prop surface.
 */

import type { ReactElement } from "react";
import { Checkbox as UiCheckbox } from "@omnicore-platform/ui";

export interface CheckboxProps {
  readonly checked: boolean;
  readonly onChange: (next: boolean) => void;
  readonly label: string;
  readonly id?: string;
}

export function Checkbox({
  checked,
  onChange,
  label,
  id,
}: CheckboxProps): ReactElement {
  return (
    <UiCheckbox
      id={id}
      checked={checked}
      aria-label={label}
      onCheckedChange={(next) => onChange(next === true)}
    />
  );
}


