/**
 * Chip — selectable pill (cog-* translation of ui.jsx `Chip`). A real toggle
 * button; `active` reflects selection via aria-pressed + a filled treatment so
 * state isn't conveyed by color alone.
 */

import type { ReactElement, ReactNode } from "react";

export interface ChipProps {
  readonly active?: boolean;
  readonly onClick: () => void;
  readonly children: ReactNode;
}

export function Chip({
  active = false,
  onClick,
  children,
}: ChipProps): ReactElement {
  return (
    <button
      type="button"
      aria-pressed={active}
      onClick={onClick}
      className={[
        "inline-flex min-h-cog-6 items-center rounded-pill px-cog-3 text-body-sm font-medium",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-2",
        active
          ? "bg-cog-blue-600 text-white dark:bg-cog-blue-300 dark:text-cog-blue-900"
          : "bg-cog-surface text-cog-text-primary ring-1 ring-inset ring-cog-border hover:bg-cog-surface-muted",
      ].join(" ")}
    >
      {children}
    </button>
  );
}


--- frontends/range-mfe/src/components/wizard/primitives/Field.tsx (71 lines) ---
/**
 * Field — labelled form-field wrapper for wizard steps (cog-* translation of
 * ui.jsx `Field`). Renders a real <label htmlFor> + optional hint via
 * aria-describedby, an optional char counter, and an optional required marker.
 * Callers supply the control as children and the localized `label`/`hint`.
 */

import type { ReactElement, ReactNode } from "react";
import { RequiredMarker } from "../../exerciseForm";

export interface FieldProps {
  /** Control id; the <label> targets it and (when hinted) aria-describedby points at `${htmlFor}-hint`. */
  readonly htmlFor: string;
  readonly label: string;
  readonly required?: boolean;
  readonly hint?: string;
  readonly count?: number;
  readonly max?: number;
  /**
   * When set, replaces the default `{count} / {max}` counter with this exact
   * (already-localized) string — e.g. a min-length hint. Takes precedence over
   * `count`/`max`.
   */
  readonly counterText?: string;
  readonly children: ReactNode;
}

export function Field({
  htmlFor,
  label,
  required = false,
  hint,
  count,
  max,
  counterText,
  children,
}: FieldProps): ReactElement {
  const hintId = hint ? `${htmlFor}-hint` : undefined;
  return (
    <div className="flex flex-col gap-cog-1">
      <label
        htmlFor={htmlFor}
        className="flex items-center justify-between text-body-sm font-semibold text-cog-text-primary"
      >
        <span>
          {label}
          {required && <RequiredMarker />}
        </span>
        {counterText !== undefined ? (
          <span className="text-body-sm font-normal text-cog-text-tertiary">
            {counterText}
          </span>
        ) : (
          count !== undefined && (
            <span className="text-body-sm font-normal text-cog-text-tertiary">
              {count}
              {max !== undefined ? ` / ${max}` : ""}
            </span>
          )
        )}
      </label>
      {children}
      {hint && (
        <p id={hintId} className="text-body-sm text-cog-text-tertiary">
          {hint}
        </p>
      )}
    </div>
  );
}


--- frontends/range-mfe/src/components/wizard/primitives/LocationCombobox.tsx (352 lines) ---
/**
 * LocationCombobox — generic pick-or-type combobox primitive for the wizard's
 * Location step (#2299 plan Task 7): country (closed 249-item list), region
 * (pick-or-type, free-text commit accepted) and city (suggest-only) all
 * share this one control. It composes `Popover` + `Combobox` from
 * `@omnicore-platform/ui` (both wrap `@radix-ui/react-popover` / `cmdk`) —
 * range-mfe forbids importing `@radix-ui/*` and `cmdk` directly
 * (`.eslintrc.cjs`), and three existing hand-rolled listboxes in this MFE
 * (`TagTypeahead`, `CharacterPinPicker`, `TagFilter`) all carry the
 * NON-EXISTENT `shadow-cog-md` token and render with no shadow — composing
 * `ui/Popover` gets §6 elevation (`shadow-cog-e4`) right for free instead.
 *
 * There is no separate "commit" step: the typed text IS `value` (matching
 * every existing free-text location field — `update({ country })` etc. fire
 * on every keystroke already), so a single `onChange` covers both typing and
 * selecting a suggestion. `items` is just the suggestion list; a value not
 * present in `items` is always accepted as free text.
 *
 * --- The two WizardOverlay traps (no existing precedent solves these) ---
 *
 * 1. Escape double-fire: `WizardOverlay.tsx` is NOT a Radix Dialog — it's a
 *    plain `role="dialog"` div with its own hand-rolled Escape handler that
 *    pops the discard-confirm dialog. Radix portals the popover content via
 *    `createPortal`, but React's *synthetic* keydown still bubbles up the
 *    REACT tree (portals don't cut synthetic bubbling) into that handler. One
 *    Escape would both close this popover AND trip the discard dialog.
 *    Fixed by `stopPropagation` in `handleInputKeyDown` below, before it can
 *    reach the overlay.
 * 2. Tab-trap leak: the overlay's hand-rolled Tab trap enumerates focusable
 *    descendants of its own dialog ref; a portaled descendant would sit under
 *    `<body>`, outside that subtree, and Tab would escape the wizard
 *    entirely. Avoided by design: focus never leaves the trigger input.
 *    Selection is driven by `aria-activedescendant` (see `optionId` below),
 *    the popover content's `onOpenAutoFocus` is suppressed, and no rendered
 *    option carries a `tabIndex`, so Tab is never pressed inside the list.
 *
 * --- cmdk id/aria overrides (no external control) ---
 *
 * cmdk's own `Combobox.Input`/`Combobox.List` hardcode `aria-expanded`,
 * `aria-label`, and `id` AFTER spreading caller props, so a caller value is
 * silently discarded (the same class of trap the plan calls out for
 * `aria-label` on `Combobox.Input`). This component sidesteps that by never
 * rendering `Combobox.Input` at all — the visible trigger is a plain `Input`
 * carrying every ARIA attribute directly — and by forcing deterministic ids
 * onto `Combobox.List`/`Combobox.Item` via a ref callback (which runs AFTER
 * cmdk sets its own generated id for that commit, so the override wins).
 * `shouldFilter={false}` on `Combobox.Root` hands filtering to `matchesSearch`
 * below so cmdk is used purely as a styled, keyboard-navigable listbox host.
 */

import {
  type ChangeEvent,
  type KeyboardEvent,
  type ReactElement,
  type RefObject,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";
import { Check, ChevronDown } from "@omnicore-platform/ui/icons";
import { Combobox, Input, Popover } from "@omnicore-platform/ui";
import { foldForMatch } from "../../../lib/locationMatch";
import { sizeClass } from "../../iconSize";

/**
 * One suggestion row: `value` is the canonical display name (rendered,
 * selected, and committed via `onChange`) and `haystacks` is every string
 * that should make this row match a typed needle — the value itself plus
 * `RegionEntry`/`CityEntry`'s `alt` aliases (ASCII transliterations, local
 * spellings, etc). The alias text is search-only: it is never rendered and
 * never becomes the committed value.
 */
export type LocationComboboxItem = { value: string; haystacks: readonly string[] };

/**
 * A caller may still pass a bare `readonly string[]` — the country list, and
 * (until the wiring task lands) the existing region/city callsite — in which
 * case each string normalizes to a single-haystack item of itself.
 */
export type LocationComboboxItemInput = string | LocationComboboxItem;

function normalizeItem(item: LocationComboboxItemInput): LocationComboboxItem {
  return typeof item === "string" ? { value: item, haystacks: [item] } : item;
}

export interface LocationComboboxProps {
  /** Control id; also the base for the generated listbox/option ids. */
  readonly id: string;
  /** Suggestion list — a closed set (country) or an open, bounded one (region/city). */
  readonly items: readonly LocationComboboxItemInput[];
  readonly value: string;
  /** Fires on every keystroke and on suggestion select — there is no separate commit step. */
  readonly onChange: (value: string) => void;
  readonly placeholder: string;
  /** Rendered via `Combobox.Empty` when no item matches the typed text. */
  readonly emptyMessage: string;
  /**
   * Optional sr-only `aria-live` announcement of the current match count
   * (e.g. `range_wizard_location_country_results_count`). Omitted for
   * suggestion lists too short to need one.
   */
  readonly resultsAnnouncement?: (count: number) => string;
  /**
   * Description text for screen readers. Only announced when
   * `hasVisibleLabel` is unset — set it when the caller already renders its
   * own `<label htmlFor>` targeting `id` (every current caller, which is
   * always `Field`-wrapped) so the name isn't double-announced. Mirrors
   * `TimezoneCombobox`'s identical seam.
   */
  readonly label: string;
  readonly hasVisibleLabel?: boolean;
  readonly disabled?: boolean;
  /** Mirrors `IconInput`'s `required`/`aria-required` wiring onto the input. */
  readonly required?: boolean;
  /** Set together with `describedBy` — mirrors `IconInput`'s existing convention. */
  readonly ariaInvalid?: boolean;
  readonly describedBy?: string;
  /**
   * Caller-owned `useValidationFocus` ref (a blocked forward-nav focuses and
   * scrolls to this field) — the call site keeps owning its own validator,
   * exactly like the existing `IconInput`/`inputRef` convention.
   */
  readonly inputRef?: RefObject<HTMLInputElement>;
}

/**
 * Diacritic-folded substring match against a pre-folded needle and a set of
 * pre-folded haystacks. Both sides are folded through `foldForMatch` (NFD
 * diacritic strip + lowercase + punctuation-to-space) BEFORE this runs, not
 * inside it — see the two `useMemo`s below — so this stays a cheap
 * `includes` scan with no per-keystroke-per-item normalization work. An
 * empty folded needle matches everything so the list stays fully browsable
 * on open before any typing (mirrors `TimezoneCombobox`'s `zoneMatchesSearch`).
 *
 * `shouldFilter={false}` on `Combobox.Root` means this is the ONLY filter —
 * cmdk's own fuzzy matcher never runs — so folding here is what lets a
 * US/English keyboard typing "Bogota" find "Bogotá", or "Munich" find
 * "München" via its alias haystack.
 */
function matchesSearch(foldedHaystacks: readonly string[], foldedNeedle: string): boolean {
  if (!foldedNeedle) return true;
  return foldedHaystacks.some((haystack) => haystack.includes(foldedNeedle));
}

export function LocationCombobox({
  id,
  items,
  value,
  onChange,
  placeholder,
  emptyMessage,
  resultsAnnouncement,
  label,
  hasVisibleLabel = false,
  disabled = false,
  required = false,
  ariaInvalid = false,
  describedBy,
  inputRef,
}: LocationComboboxProps): ReactElement {
  const [open, setOpen] = useState(false);
  const [activeValue, setActiveValue] = useState("");
  const fallbackRef = useRef<HTMLInputElement>(null);
  const resolvedInputRef = inputRef ?? fallbackRef;
  const generatedId = useId();
  const listboxId = `${id}-listbox`;
  const descriptionId = `${generatedId}-description`;

  // Fold every item's haystacks ONCE per `items` array, not once per
  // keystroke per item — city shards (`cities15000`) run to thousands of
  // entries, and this filter runs on every keystroke.
  const foldedItems = useMemo(
    () =>
      items.map((item) => {
        const normalized = normalizeItem(item);
        return {
          value: normalized.value,
          foldedHaystacks: normalized.haystacks.map(foldForMatch),
        };
      }),
    [items],
  );
  // The needle folds once per render, not once per item.
  const foldedNeedle = useMemo(() => foldForMatch(value), [value]);

  // Guard: an empty string must never become a selectable row — selecting it
  // would clear the field, exactly the blank-row trap TimezoneCombobox's
  // value-not-in-list guard exists to avoid. Also filters out a `value` not
  // present in `items` — free text is accepted via typing, never as a
  // synthetic list row.
  const filteredItems = useMemo(
    () =>
      foldedItems.filter(
        (item) => item.value !== "" && matchesSearch(item.foldedHaystacks, foldedNeedle),
      ),
    [foldedItems, foldedNeedle],
  );
  const activeIndex = filteredItems.findIndex((item) => item.value === activeValue);

  function optionId(index: number): string {
    return `${id}-option-${index}`;
  }

  function handleOpenChange(next: boolean): void {
    if (disabled) return;
    setOpen(next);
  }

  function handleInputChange(e: ChangeEvent<HTMLInputElement>): void {
    onChange(e.target.value);
    if (!open) setOpen(true);
  }

  function handleSelect(item: string): void {
    onChange(item);
    setActiveValue(item);
    setOpen(false);
  }

  function handleInputKeyDown(e: KeyboardEvent<HTMLInputElement>): void {
    if (e.key === "Escape") {
      if (open) {
        // See the module doc's Escape-double-fire trap: stop this here so
        // WizardOverlay's own Escape handler never sees it.
        e.stopPropagation();
        setOpen(false);
      }
      return;
    }
    if (e.key === "ArrowDown" && !open) {
      setOpen(true);
      return;
    }
    if (e.key === "Enter" && open && activeIndex < 0) {
      // Nothing is aria-selected (the user never pressed ArrowDown to sync
      // `activeValue`), so cmdk's own Root Enter-handling — which dispatches
      // select on the aria-selected item — has nothing to act on. That's
      // true whether nothing matches at all, or exactly one item matches the
      // typed text but was never highlighted. Either way the typed text is
      // already the committed value (every keystroke fires `onChange`) —
      // Enter just closes.
      e.preventDefault();
      setOpen(false);
    }
  }

  const describedByIds = [
    hasVisibleLabel ? undefined : descriptionId,
    ariaInvalid ? describedBy : undefined,
  ]
    .filter((part): part is string => Boolean(part))
    .join(" ");

  return (
    <Popover.Root open={open} onOpenChange={handleOpenChange}>
      <Combobox.Root
        shouldFilter={false}
        value={activeValue}
        onValueChange={setActiveValue}
        label={placeholder}
      >
        <div className="relative">
          <Popover.Trigger asChild>
            <Input
              ref={resolvedInputRef}
              id={id}
              type="text"
              role="combobox"
              aria-expanded={open}
              aria-controls={listboxId}
              aria-autocomplete="list"
              aria-activedescendant={
                open && activeIndex >= 0 ? optionId(activeIndex) : undefined
              }
              aria-invalid={ariaInvalid ? true : undefined}
              aria-describedby={describedByIds || undefined}
              autoComplete="off"
              disabled={disabled}
              required={required}
              aria-required={required ? true : undefined}
              value={value}
              placeholder={placeholder}
              className="pe-cog-8"
              onChange={handleInputChange}
              onKeyDown={handleInputKeyDown}
            />
          </Popover.Trigger>
          {/* Decorative — a vertical chevron per the RTL contract (never a
              horizontal arrow glyph); the input's own value/placeholder
              carries the state, this is affordance only. */}
          <ChevronDown
            aria-hidden="true"
            focusable="false"
            className={`pointer-events-none absolute inset-y-cog-0 end-cog-3 my-auto text-cog-text-tertiary ${sizeClass(16)}`}
          />
        </div>
        {hasVisibleLabel ? null : (
          <span id={descriptionId} className="sr-only">
            {label}
          </span>
        )}
        <Popover.Content
          align="start"
          // Keep focus on the trigger input — see the module doc's Tab-trap
          // leak trap. Radix would otherwise auto-focus into the portaled
          // content on open, which is a subtree the overlay's hand-rolled
          // Tab trap never sees.
          onOpenAutoFocus={(e) => e.preventDefault()}
          className="w-[--radix-popover-trigger-width] min-w-cog-18 p-cog-2"
        >
          <Combobox.List
            className="max-h-cog-19 overflow-y-auto"
            // Belt-and-suspenders: option rows carry no tabIndex so a click
            // never moves focus off the input in the first place, but this
            // also keeps a mousedown from ever being treated as a blur.
            onMouseDown={(e) => e.preventDefault()}
            ref={(node) => {
              if (node) node.id = listboxId;
            }}
          >
            <Combobox.Empty className="px-cog-2 py-cog-2 text-body-sm text-cog-text-tertiary">
              {emptyMessage}
            </Combobox.Empty>
            {filteredItems.map((item, index) => (
              <Combobox.Item
                key={item.value}
                value={item.value}
                onSelect={() => handleSelect(item.value)}
                className="flex items-center justify-between gap-cog-2 text-start"
                ref={(node) => {
                  if (node) node.id = optionId(index);
                }}
              >
                <span className="text-start">{item.value}</span>
                {item.value === value ? (
                  <Check aria-hidden="true" focusable="false" className={sizeClass(14)} />
                ) : null}
              </Combobox.Item>
            ))}
          </Combobox.List>
          {resultsAnnouncement ? (
            <span role="status" aria-live="polite" className="sr-only">
              {resultsAnnouncement(filteredItems.length)}
            </span>
          ) : null}
        </Popover.Content>
      </Combobox.Root>
    </Popover.Root>
  );
}


