/**
 * ReviewLaunchCard — the hero summary at the top of the Review step (#2153).
 *
 * It answers "what am I about to create?" in one glance — name, dates,
 * location, headcount, description — and carries the completion meter, so the
 * final step reads as a launch moment rather than the ninth identical card in a
 * stack. It replaces the old Basics summary card outright: the exercise name IS
 * this card's heading, and its Edit jumps to Basics, so nothing is summarized
 * twice.
 *
 * The meter is decorative (aria-hidden): the same fraction is stated in text
 * beside it, which is the accessible signal.
 */

import type { ReactElement } from "react";
import type { LucideIcon } from "@omnicore-platform/ui/icons";
import {
  CalendarDays,
  Check,
  MapPin,
  Users,
} from "@omnicore-platform/ui/icons";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { NotSetLine } from "./NotSetLine";

/** Geometry of the completion ring — r is the only free value. */
const RING_RADIUS = 15;
const RING_CIRCUMFERENCE = 2 * Math.PI * RING_RADIUS;

export interface ReviewLaunchCardProps {
  readonly name: string;
  /** Preformatted, localized date range; null when the draft carries none. */
  readonly dateRange: string | null;
  /** Preformatted, localized location; null when the draft carries none. */
  readonly location: string | null;
  readonly description: string;
  readonly factionCount: number;
  readonly profileCount: number;
  readonly generateBaseline: boolean;
  readonly stepsComplete: number;
  readonly stepsTotal: number;
  readonly onEdit: () => void;
}

/** One icon + text fact in the hero's meta row. */
function Fact({
  icon: Icon,
  children,
  testId,
}: {
  icon: LucideIcon;
  children: ReactElement | string;
  testId?: string;
}): ReactElement {
  return (
    <span
      data-testid={testId}
      className="inline-flex items-center gap-cog-1-5 text-body-sm text-cog-text-secondary"
    >
      <Icon
        aria-hidden="true"
        width={undefined}
        height={undefined}
        className="h-cog-3-5 w-cog-3-5 text-cog-text-tertiary"
      />
      {children}
    </span>
  );
}

export function ReviewLaunchCard({
  name,
  dateRange,
  location,
  description,
  factionCount,
  profileCount,
  generateBaseline,
  stepsComplete,
  stepsTotal,
  onEdit,
}: ReviewLaunchCardProps): ReactElement {
  const remaining = stepsTotal - stepsComplete;
  const filled = stepsTotal === 0 ? 0 : stepsComplete / stepsTotal;

  return (
    <section
      data-testid="review-launch-card"
      className="rounded-xl border border-cog-border bg-gradient-to-b from-cog-violet-50 to-cog-surface p-cog-4-5 shadow-cog-e1 dark:from-cog-violet-900/40 dark:to-cog-surface dark:shadow-cog-e1-dark"
    >
      <div className="flex flex-col gap-cog-4 sm:flex-row sm:items-start sm:justify-between">
        <div className="flex min-w-cog-0 flex-col gap-cog-2">
          <span className="text-eyebrow uppercase text-cog-violet-600 dark:text-cog-violet-dark-fg">
            {m.range_wizard_review_ready_eyebrow()}
          </span>
          <div className="flex items-center gap-cog-2">
            <h3 className="text-display-lg text-cog-text-primary">
              {name || m.range_wizard_review_untitled()}
            </h3>
            <button
              type="button"
              onClick={onEdit}
              className={[
                "rounded-md px-cog-2 py-cog-0-5 text-body-sm font-medium",
                "text-cog-blue-600 dark:text-cog-blue-300",
                "hover:bg-cog-surface-muted",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-2",
              ].join(" ")}
            >
              {m.range_wizard_review_edit()}
            </button>
          </div>

          <div className="flex flex-wrap items-center gap-x-cog-4 gap-y-cog-1-5">
            <Fact icon={CalendarDays} testId="review-launch-dates">
              {dateRange ?? <NotSetLine />}
            </Fact>
            <Fact icon={MapPin}>{location ?? <NotSetLine />}</Fact>
            {factionCount > 0 && (
              <Fact icon={Users}>
                {m.range_wizard_review_hero_population({
                  factions: factionCount,
                  profiles: profileCount,
                })}
              </Fact>
            )}
          </div>

          <p className="max-w-prose text-body-md text-cog-text-secondary [text-wrap:pretty]">
            {description || (
              <span className="text-cog-text-tertiary">
                {m.range_wizard_review_no_description()}
              </span>
            )}
          </p>
        </div>

        <div className="flex shrink-0 flex-col items-start gap-cog-2 sm:items-end">
          <div className="flex items-center gap-cog-2-5 rounded-lg border border-cog-border bg-cog-surface px-cog-3 py-cog-2">
            <svg
              data-testid="review-progress-meter"
              aria-hidden="true"
              viewBox="0 0 36 36"
              className="h-cog-6-5 w-cog-6-5 -rotate-90"
            >
              <circle
                cx="18"
                cy="18"
                r={RING_RADIUS}
                fill="none"
                strokeWidth="4"
                className="stroke-cog-surface-muted"
              />
              <circle
                cx="18"
                cy="18"
                r={RING_RADIUS}
                fill="none"
                strokeWidth="4"
                strokeLinecap="round"
                strokeDasharray={RING_CIRCUMFERENCE}
                strokeDashoffset={RING_CIRCUMFERENCE * (1 - filled)}
                className="stroke-cog-success-600 dark:stroke-cog-success-dark"
              />
            </svg>
            <span className="flex flex-col">
              <span className="text-body-md font-semibold text-cog-text-primary">
                {m.range_wizard_review_progress({
                  done: stepsComplete,
                  total: stepsTotal,
                })}
              </span>
              <span className="text-caption text-cog-text-tertiary">
                {remaining === 0
                  ? m.range_wizard_review_progress_all_done()
                  : m.range_wizard_review_progress_remaining({
                      count: remaining,
                    })}
              </span>
            </span>
          </div>

          {generateBaseline && (
            <span
              role="status"
              className="inline-flex items-center gap-cog-1 rounded-pill bg-cog-success-700/10 px-cog-2 py-cog-0-5 text-body-sm font-medium text-cog-success-700 dark:text-cog-success-dark ring-1 ring-inset ring-cog-success-700/30"
            >
              <Check
                aria-hidden="true"
                width={undefined}
                height={undefined}
                className="h-cog-3 w-cog-3"
              />
              {m.range_wizard_review_baseline_badge()}
            </span>
          )}
        </div>
      </div>
    </section>
  );
}


