--- frontends/range-mfe/src/components/wizard/primitives/Toggle.tsx (53 lines) ---
/**
 * Toggle — thin adapter over `@omnicore-platform/ui`'s `Switch`.
 *
 * The wizard's call sites (StepConfig's ToggleRow etc.) pass a
 * `checked`/`onChange`/`label` prop surface; `Switch` (Radix-backed) expects
 * `checked`/`onCheckedChange` and takes its accessible name via `aria-label`
 * rather than a bespoke `label` prop. This adapter bridges that shape gap so
 * call sites don't change, while inheriting `Switch`'s correct RTL thumb
 * travel (`rtl:` variants that mirror the translate under dir="rtl") — the
 * bug this migration fixes: the old hand-rolled thumb ignored writing
 * direction entirely and slid the wrong way under ar-AE.
 */

import type { ReactElement } from "react";

import { Switch } from "@omnicore-platform/ui";

export interface ToggleProps {
  readonly checked: boolean;
  readonly onChange: (next: boolean) => void;
  readonly label: string;
  readonly id?: string;
  readonly disabled?: boolean;
}

export function Toggle({
  checked,
  onChange,
  label,
  id,
  disabled = false,
}: ToggleProps): ReactElement {
  return (
    <Switch
      id={id}
      checked={checked}
      onCheckedChange={onChange}
      aria-label={label}
      disabled={disabled}
      // Switch defaults to suppressing same-target activations within
      // ~100ms (see Switch.tsx) to guard against double-click/hardware
      // mouse chatter. The wizard toggle is a settings control, not a
      // pointer-chatter-prone surface — a deliberate rapid off-then-on
      // (e.g. "toggling generateBaseline off then on" to reset derived
      // state) is legitimate intent here, and the hand-rolled Toggle this
      // adapter replaces never suppressed rapid activations. Opt out to
      // preserve that pre-migration behaviour; this migration's remit was
      // the RTL thumb-direction fix only.
      suppressClickBursts={false}
    />
  );
}


