/**
 * WebsitePill — selectable pill for choosing a website/outlet in the wizard.
 * Visually `Chip`'s filled treatment (rounded-pill, filled selected state);
 * semantically `Checkbox`'s toggle contract (role="checkbox" + aria-checked,
 * real accessible name, `disabled` support). Deliberately not built by
 * extending either — `Chip` has no `disabled`/icon slot and live call sites
 * an invasive signature change could regress; `Checkbox` is a fixed-size
 * square glyph, not a labeled pill.
 *
 * Selection is conveyed by more than color alone. Three cues change together:
 * the pill takes a solid fill, its visible border disappears, and its label
 * shifts to a heavier weight — so weight and border presence still read the
 * state when hue does not. `aria-checked` carries the same information to
 * assistive technology. Both states declare the same ring and padding metrics
 * (the selected ring is simply transparent) so toggling never shifts layout.
 * Long outlet names are truncated with `title` exposing the full name so a
 * single pill can't stretch the group.
 */

import type { ReactElement } from "react";

export interface WebsitePillProps {
  readonly checked: boolean;
  readonly onChange: (next: boolean) => void;
  readonly label: string;
  readonly id?: string;
  readonly disabled?: boolean;
}

export function WebsitePill({
  checked,
  onChange,
  label,
  id,
  disabled = false,
}: WebsitePillProps): ReactElement {
  return (
    <button
      type="button"
      role="checkbox"
      id={id}
      aria-checked={checked}
      disabled={disabled}
      title={label}
      onClick={() => onChange(!checked)}
      className={[
        "inline-flex max-w-cog-27 min-h-btn-sm items-center rounded-pill px-cog-3 text-body-sm ring-1 ring-inset",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-2",
        checked
          ? "bg-cog-blue-600 font-semibold text-white ring-transparent dark:bg-cog-blue-300 dark:text-cog-blue-900"
          : "bg-cog-surface font-medium text-cog-text-secondary ring-cog-border hover:bg-cog-surface-muted",
        disabled ? "cursor-not-allowed opacity-60" : "",
      ].join(" ")}
    >
      <span className="truncate">{label}</span>
    </button>
  );
}


