/**
 * AiHero — loading vs idle branch coverage.
 *
 * The loading branch swaps the filled brand-blue tile for a bare 56px
 * ThinkingOrb (brand-blue particles on `cog-surface` measure ~7.4:1/8:1
 * light/dark; the old white-on-`cog-blue-300` ring measured ~1.6:1 in dark
 * mode — illegible). `role="status" aria-live="polite"` lives on the
 * heading+body wrapper so the already-visible localized copy is what gets
 * announced, with no `sr-only` duplicate and no inert empty-span status.
 *
 * The region is present UNCONDITIONALLY, in both idle and loading — NOT
 * gated on `loading` (finding 9, progress-and-cancel-ai review): assistive
 * tech only announces a mutation to a region that was already live at
 * mutation time, so adding `role="status"` in the same commit that swaps in
 * the loading copy frequently drops the announcement entirely. Keeping the
 * region permanently mounted also means this is the single stable status
 * node for the whole card across every phase — JobStatusInline's "hero"
 * variant defers to it and never mounts a region of its own (see
 * JobStatusInline.tsx), so it can never coexist with a second live region.
 */
import { afterEach, describe, expect, it } from "vitest";
import { cleanup, render, screen } from "@testing-library/react";
import { AiHero } from "./AiHero";

// react/jsx-no-literals (i18n gate) flags raw JSX text children; this
// fixture button label is test scaffolding, not user-facing copy, so it's
// routed through a named constant to keep the same guard happy.
const CANCEL_LABEL = "Cancel";

afterEach(() => {
  cleanup();
});

describe("AiHero — idle branch", () => {
  it("renders the filled tile with the icon, no canvas", () => {
    const { container } = render(
      <AiHero heading="Ready to discover" body="We will scan the web." />,
    );

    expect(container.querySelector("canvas")).toBeNull();

    const tile = container.querySelector(".bg-cog-blue-600");
    expect(tile).not.toBeNull();
    expect(tile).toHaveAttribute("aria-hidden", "true");

    expect(screen.getByText("Ready to discover")).toBeInTheDocument();
    expect(screen.getByText("We will scan the web.")).toBeInTheDocument();
  });

  // Finding 9 (progress-and-cancel-ai review): the status region is
  // permanently mounted, even while idle — not added only once loading
  // starts — so assistive tech is already tracking it before the mutation
  // into the loading copy happens.
  it("already carries a live status region while idle, containing the idle copy", () => {
    render(<AiHero heading="Ready to discover" body="We will scan the web." />);

    const status = screen.getByRole("status");
    expect(status).toHaveAttribute("aria-live", "polite");
    expect(status).toHaveTextContent("Ready to discover");
    expect(status).toHaveTextContent("We will scan the web.");
  });
});

describe("AiHero — loading branch", () => {
  it("renders a canvas orb instead of the filled tile", () => {
    const { container } = render(
      <AiHero loading heading="Discovering factions" body="Hang tight." />,
    );

    expect(container.querySelector("canvas")).not.toBeNull();
    expect(container.querySelector(".bg-cog-blue-600")).toBeNull();
  });

  it("renders exactly one status-role node, containing the heading text", () => {
    render(<AiHero loading heading="Discovering factions" body="Hang tight." />);

    const statusNodes = screen.getAllByRole("status");
    expect(statusNodes.length).toBe(1);
    expect(statusNodes[0]).toHaveAttribute("aria-live", "polite");
    expect(statusNodes[0]).toHaveTextContent("Discovering factions");
    expect(statusNodes[0]).toHaveTextContent("Hang tight.");
  });

  it("keeps the orb aria-hidden and role-free (does not add a second status node)", () => {
    const { container } = render(
      <AiHero loading heading="Discovering factions" body="Hang tight." />,
    );

    const canvas = container.querySelector("canvas");
    expect(canvas).toHaveAttribute("aria-hidden", "true");
    expect(canvas?.getAttribute("role")).toBeNull();
  });

  // Finding 9 regression: the fix is only meaningful if the SAME live-region
  // node survives the idle→loading transition (a screen reader has to have
  // been tracking this exact node before the mutation for the mutation to
  // be announced) — asserting the node reference is unchanged across
  // rerender pins that role="status" is never removed-then-readded.
  it("keeps the identical status-region node across the idle→loading transition", () => {
    const { rerender } = render(
      <AiHero heading="Ready to discover" body="We will scan the web." />,
    );
    const before = screen.getByRole("status");

    rerender(<AiHero loading heading="Discovering factions" body="Hang tight." />);
    const after = screen.getByRole("status");

    expect(after).toBe(before);
    expect(after).toHaveTextContent("Discovering factions");
  });

  it("defaults orbMode to 'orbits' and forwards an explicit orbMode to the orb's mount", () => {
    // ThinkingOrb renders the same canvas markup regardless of mode (mode is
    // consumed by the OrbEngine draw loop, not reflected as a DOM attribute),
    // so we assert the orb mounts cleanly under both the default and an
    // explicit "scan" mode without throwing — the forwarding contract itself
    // is exercised at the ThinkingOrb layer (see ThinkingOrb.test.tsx).
    expect(() =>
      render(<AiHero loading heading="h" body="b" />),
    ).not.toThrow();

    expect(() =>
      render(<AiHero loading orbMode="scan" heading="h" body="b" />),
    ).not.toThrow();
  });
});

describe("AiHero — heading/body survive across states", () => {
  it("keeps rendering the passed icon in idle state", () => {
    const { container } = render(
      <AiHero icon="barChart" heading="Analyze" body="Body copy" />,
    );
    expect(container.querySelector("svg")).not.toBeNull();
  });

  it("still renders context rows and children alongside the loading orb", () => {
    render(
      <AiHero
        loading
        heading="Discovering"
        body="Body copy"
        context={[{ label: "Location", value: "Berlin" }]}
      >
        <button type="button">{CANCEL_LABEL}</button>
      </AiHero>,
    );

    expect(screen.getByText("Location")).toBeInTheDocument();
    expect(screen.getByText("Berlin")).toBeInTheDocument();
    expect(screen.getByRole("button", { name: CANCEL_LABEL })).toBeInTheDocument();
  });
});


